function options(rows,selected,userContent=false){return rows.map(([value,label])=>'<option'+(userContent?' data-user-content':'')+' value="'+esc(value)+'"'+(String(value)===String(selected)?' selected':'')+'>'+esc(label)+'</option>').join('');}
