 const html='<h1>Projects & vessels</h1><p class="next-intro">Keep related calculations together, retain their inputs and compare results before preparing a combined report.</p>'+subnav([['projects','Projects'],['workflow','Linked calculations']])+'<div class="next-grid"><section class="panel"><h2>Create a project</h2><form id="project-create"><label>Project title<input id="project-title" maxlength="200" required></label><label>Vessel profile<select id="project-vessel"><option value="">No vessel attached</option>'+options(data.vessels.map(v=>[v.id,v.name]),undefined,true)+'</select></label><button type="submit">Create project</button></form></section><section class="panel"><h2>Vessel library</h2><p>Save the current vessel configuration under a name, then switch between saved configurations.</p><form id="vessel-save"><label>Profile name<input id="vessel-name" maxlength="200" required></label><button type="submit">Save current vessel</button></form><div class="next-actions"><select id="vessel-select" aria-label="Saved vessel profile">'+options(data.vessels.map(v=>[v.id,v.name]),undefined,true)+'</select><button id="vessel-apply"'+(!data.vessels.length?' disabled':'')+'>Use this vessel</button><a href="index.html?page=profile">Configure active vessel →</a></div></section></div><section class="panel"><h2>Saved projects</h2>'+(data.projects.length?'<label>Selected project<select id="project-select">'+options(data.projects.map(p=>[p.id,p.title]),selected,true)+'</select></label>':empty('Create your first project to save calculations.'))+(project?'<div class="next-actions"><button id="project-rename">Rename project</button><button id="project-report"'+(!cases.length?' disabled':'')+'>Combined report (HTML / PDF)</button><button id="project-delete">Delete project</button></div><p>'+cases.length+' saved calculations.</p>'+cases.map(c=>'<details class="next-source"><summary>'+user(c.title)+' · '+esc(c.modelId)+'</summary><p>Captured '+esc(new Date(c.createdAt).toLocaleString())+'</p>'+table(['Result','Saved value'],Object.entries(c.snapshot.results||{}).map(([k,v])=>[k,typeof v==='object'?E.displayValue(v):v]))+'<div class="next-actions"><button data-case-report="'+esc(c.id)+'">Calculation report</button><button data-case-delete="'+esc(c.id)+'">Remove calculation</button></div></details>').join(''):'')+'</section><section class="panel"><h2>Bring a calculation into this project</h2><p>Experiments have a Save to project action. You can also import a recent calculation from the main tools.</p>'+(recent.length&&project?'<label>Recent calculation<select id="recent-select">'+options(recent.map((r,i)=>[i,r.title+' · '+r.time]))+'</select></label><button id="recent-save">Save selected calculation</button>':empty('Calculate with a main tool or save an Education experiment, then return here.'))+'<div class="next-actions"><a href="index.html">Open main tools →</a><a href="#analysis">Open an experiment →</a></div></section>';
